function swatches(key,label){return `<div class="section-row"><span class="section-title">${label}</span><span class="hint">${key==='skin'?'Skin tone':key==='hairColor'?'Hair color':'Eye color'}</span></div><div class="swatches">${palettes[key].map((c,i)=>`<button class="swatch ${state[key]===i?'selected':''}" data-key="${key}" data-value="${i}" style="background:${c}" aria-label="${label} ${i+1}"></button>`).join('')}</div>`}
function chips(key,label,values){return `<div class="section-row"><span class="section-title">${label}</span></div><div class="chips">${values.map(v=>`<button class="chip ${state[key]===v?'selected':''}" data-key="${key}" data-value="${v}">${v}</button>`).join('')}</div>`}
function render(){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.tab));let html='';if(state.tab==='look'){html+=chips('age','LIFE STAGE',['Young Adult','Adult','Elder']);html+=chips('gender','FRAME',['Feminine','Masculine']);html+=swatches('skin','COMPLEXION');html+=`<div class="section-row"><span class="section-title">HAIRSTYLE</span><span class="hint">Choose a look</span></div><div class="haircards">${['〰','⌒','✿','◠'].map((h,i)=>`<button class="haircard ${state.hair===i?'active':''}" data-key="hair" data-value="${i}"><span class="hair-icon" style="color:${hairs[state.hairColor]}">${h}</span><small>${['Waves','Bob','Curls','Pixie'][i]}</small></button>`).join('')}</div>${swatches('hairColor','HAIR COLOR')}${swatches('eyes','EYE COLOR')}`}else if(state.tab==='style'){html+=`<div class="section-row"><span class="section-title">EVERYDAY LOOK</span><span class="hint">Pick an outfit</span></div><div class="haircards" style="grid-template-columns:repeat(5,1fr)">${clothes.map((c,i)=>`<button class="haircard ${state.outfit===i?'active':''}" data-key="outfit" data-value="${i}"><span class="hair-icon" style="color:${c[0]}">✦</span><small>${['Soft','Classic','Garden','Golden','Indie'][i]}</small></button>`).join('')}</div>${chips('body','BODY SHAPE',['Petite','Average','Athletic','Curvy'])}<div class="section-row"><span class="section-title">COLOR STORY</span></div><div class="swatches">${clothes.map((c,i)=>`<button class="swatch ${state.outfit===i?'selected':''}" data-key="outfit" data-value="${i}" style="background:${c[0]}" aria-label="Outfit ${i+1}"></button>`).join('')}</div><div style="padding:13px;border-radius:6px;background:#f6f0ed;color:#837685;font-size:10px;line-height:1.6">✧ &nbsp; A good outfit should feel like <i>you</i>. Choose a color that makes you feel at home.</div>`}else{html+=`<div class="section-row"><span class="section-title">WHAT MAKES THEM, THEM?</span><span class="hint">Choose up to 3</span></div>${[['Creative','✎','Always dreaming up something new.'],['Cheerful','☼','Finds a little sunshine everywhere.'],['Bookworm','▤','Happiest with a story in hand.'],['Outdoorsy','❋','Feels most alive under open skies.'],['Romantic','♡','Believes in the magic of connection.'],['Ambitious','↗','Has big plans for the future.'],['Goofball','☻','Can always make you laugh.'],['Loyal','✧','The friend who always shows up.']].map(([n,ico,desc])=>`<label class="trait"><span class="trait-icon">${ico}</span><span><b>${n}</b><small>${desc}</small></span><input type="checkbox" data-trait="${n}" ${state.traits.includes(n)?'checked':''} ${!state.traits.includes(n)&&state.traits.length>=3?'disabled':''}></label>`).join('')}<label class="field-label" for="simName" style="margin-top:16px">SIM NAME</label><input id="simName" class="name-input" maxlength="24" value="${state.name.replaceAll('"','&quot;')}" placeholder="Give your Sim a name">`}
panel.innerHTML=html;panel.querySelectorAll('[data-key]').forEach(el=>el.addEventListener('click',()=>{let k=el.dataset.key;let v=['skin','hairColor','eyes','hair','outfit'].includes(k)?Number(el.dataset.value):el.dataset.value;state[k]=v;render();drawSim()}));panel.querySelectorAll('[data-trait]').forEach(el=>el.addEventListener('change',()=>{const t=el.dataset.trait;if(el.checked){if(state.traits.length>=3){el.checked=false;toast('Choose up to three traits');return}state.traits.push(t)}else state.traits=state.traits.filter(x=>x!==t);render()}));const inp=document.getElementById('simName');if(inp)inp.addEventListener('input',()=>{state.name=inp.value||'Your Sim';document.getElementById('plateName').textContent=state.name});}
