document.getElementById('randomBtn').onclick=randomize;document.getElementById('randomTop').onclick=randomize;
document.getElementById('turnLeft').onclick=()=>{state.angle-=.35;drawSim()};document.getElementById('turnRight').onclick=()=>{state.angle+=.35;drawSim()};document.getElementById('spin').onclick=()=>{state.angle+=Math.PI/2;drawSim();toast('Turn your Sim to see their look')};document.getElementById('zoom').onclick=()=>{state.zoom=state.zoom===1?1.13:1;drawSim()};
let down=false,lastX=0;const drag=document.getElementById('dragArea');drag.addEventListener('pointerdown',e=>{down=true;lastX=e.clientX;drag.setPointerCapture(e.pointerId)});drag.addEventListener('pointermove',e=>{if(!down)return;state.angle+=(e.clientX-lastX)*.013;lastX=e.clientX;drawSim()});drag.addEventListener('pointerup',()=>down=false);drag.addEventListener('pointercancel',()=>down=false);
document.getElementById('sound').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♫'?'♪':'♫';toast('Sound settings updated')};
document.getElementById('finishBtn').onclick=()=>{const activeInput=document.getElementById('simName');if(activeInput)state.name=activeInput.value.trim()||'Your Sim';const profile={...state,createdAt:new Date().toISOString()};localStorage.setItem('evergreen-sim',JSON.stringify(profile));document.getElementById('createdName').textContent=state.name;document.getElementById('createdText').textContent=`${state.name} is a ${state.age.toLowerCase()} with a ${state.traits.slice(0,2).join(' and ').toLowerCase()} spirit. Their next chapter is waiting to be written.`;document.getElementById('cardStats').innerHTML=`<span>${state.age}</span><span>${state.traits[0]||'One of a kind'}</span><span>${['Soft','Classic','Garden','Golden','Indie'][state.outfit]} style</span>`;document.getElementById('created').classList.add('open')};document.getElementById('again').onclick=()=>document.getElementById('created').classList.remove('open');
render();drawSim();
